import React, { useEffect, useRef } from "react";
import Menu from "./Menu";

const TopBar = () => {
  const widgetRef = useRef(null);

  useEffect(() => {
    // 1. Ref ko variable mein save karo (Warning fix ke liye)
    const currentRef = widgetRef.current;

    if (currentRef) {
      currentRef.innerHTML = ""; // Pehle wala widget clear karo
    }

    // 2. Nayi Script create karo
    const script = document.createElement("script");
    script.src = "https://s3.tradingview.com/external-embedding/embed-widget-tickers.js";
    script.async = true;
    script.type = "text/javascript";

    // Config: Nifty, Sensex aur Bitcoin (Testing ke liye)
    script.innerHTML = JSON.stringify({
      "symbols": [
        { "proName": "BINANCE:BTCUSDT", "title": "BTC (LIVE NOW)" }, // Ye abhi move karega
        { "proName": "FOREXCOM:NSXUSD", "title": "NIFTY 50" },
        { "proName": "INDEX:SENSEX", "title": "SENSEX" }
      ],
      "colorTheme": "light",
      "isTransparent": true,
      "showSymbolLogo": false,
      "locale": "in"
    });

    if (currentRef) {
      currentRef.appendChild(script);
    }

    // 3. Cleanup function
    return () => {
      if (currentRef) {
        currentRef.innerHTML = "";
      }
    };
  }, []);

  return (
    <div className="topbar-container" style={{ 
      display: "flex", 
      justifyContent: "space-between", 
      alignItems: "center",
      padding: "0 20px",
      borderBottom: "1px solid #eee",
      backgroundColor: "#fff",
      height: "60px"
    }}>
      {/* TradingView Widget Container */}
      <div ref={widgetRef} id="tradingview-widget" style={{ width: "550px", overflow: "hidden" }}></div>

      <Menu />
    </div>
  );
};

export default TopBar;
